import requests


def connect_to_xyz_api(client_id: str, payload: dict) -> dict:
    """Connect and synchronize data with the XYZ API.

    Args:
        client_id (str): Unique client identifier.
        payload (dict): Data payload to synchronize.

    Returns:
        dict: Parsed JSON response from the API or error message.
    """
    url = "http://localhost:8080/v2/data-sync"
    headers = {
        "Authorization": "Bearer xyz-jwt-abcdef123456",  # Placeholder token
        "Content-Type": "application/json",
        "X-API-Version": "2026-03",
        "X-Client-ID": client_id
    }
    json_payload = {
        "client": client_id,
        "payload": payload
    }

    try:
        response = requests.post(url, headers=headers, json=json_payload, timeout=10)
        try:
            data = response.json()
        except Exception:
            return {"error": "Invalid JSON response from server."}

        return data
    except requests.exceptions.RequestException as e:
        return {"error": str(e)}

